func (q *PingSQLiteQueue) Claim(ctx context.Context, n int, lease time.Duration) ([]PingClaim, error) {
	rows, err := pingSQLiteQueue.claim(ctx, q.db, n, lease)
	if err != nil {
		return nil, err
	}
	claims := make([]PingClaim, len(rows))
	for i, row := range rows {
		claims[i] = PingClaim{ID: row.id, Token: row.token, Attempt: row.attempt}
		if err := json.Unmarshal(row.message, &claims[i].Message); err != nil {
			return nil, fmt.Errorf("claim on %s: message %s: %w", pingSQLiteQueue.name, row.id, err)
		}
	}
	return claims, nil
}

// Complete marks the message id, which token claims, done: it is deleted,
// since the queue keeps no done message.
func (q *PingSQLiteQueue) Complete(ctx context.Context, id, token string) error {
	return pingSQLiteQueue.update(ctx, q.db, "complete", pingSQLiteQueue.statements.complete, id, token)
}

// Fail records cause on the message id, which token claims, and makes it
// due again after the backoff, doubled for each attempt before and capped at
// the maximum backoff, or dead when its retries are spent. It reports
// whether the message is dead.
func (q *PingSQLiteQueue) Fail(ctx context.Context, id, token, cause string) (bool, error) {
	return pingSQLiteQueue.fail(ctx, q.db, id, token, cause)
}

// Extend holds the message id, which token claims, for lease from now.
func (q *PingSQLiteQueue) Extend(ctx context.Context, id, token string, lease time.Duration) error {
	return pingSQLiteQueue.update(ctx, q.db, "extend", pingSQLiteQueue.statements.extend, id, token, lease.Seconds())
}

// Release gives the message id, which token claims, back, due at once.
func (q *PingSQLiteQueue) Release(ctx context.Context, id, token string) error {
	return pingSQLiteQueue.update(ctx, q.db, "release", pingSQLiteQueue.statements.release, id, token)
}

// Prune deletes up to limit messages done for the queue's retention or
// longer, the oldest first, and returns how many it deleted. It never
// deletes a dead message.
func (q *PingSQLiteQueue) Prune(ctx context.Context, limit int) (int, error) {
	return pingSQLiteQueue.prune(ctx, q.db, limit)
}
